     SUB("Lines of artillery were positioned near the summit along the northern and western borders of Evergreen Cemetery, with caissons, battery horses and support units among the grave plots", 'documented', 'supported', ['nps_art']),
     SUB("It was reported that General Howard ordered troops to lay the headstones flat on the ground to prevent their destruction", 'documented', 'supported', ['nps_rep', 'nps_howard1', 'nps_howard2'], "reported (hearsay) in a modern government report; the date inside the battle is not stated"),
     SUB("Troops tore down wood and stone fences to remove obstacles and built up stone fences as breastworks", 'documented', 'supported', ['nps_fences1', 'nps_fences2']),
     SUB("Battle damage in Evergreen Cemetery included bullet holes and cracks in some of the grave markers, damage to grave plot fences, and removal of planks from the fences along Baltimore Pike", 'documented', 'supported', ['nps_damage']),
     SUB("The gatehouse suffered smashed windows and several holes in the brick walls", 'documented', 'supported', ['nps_gate']),
